-- ===========================================================================
-- Hand-written below: what Prisma cannot express.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- One open shift per person (plan §4.7).
--
-- A scan closes the open record or opens a new one; two scans racing for
-- one person must not both open one, whatever the service read first. The
-- scan also takes an advisory lock (TAY's pattern); this index is the
-- backstop. Closed shifts are history and leave the index.
--
-- Named as Prisma names a unique index (`<Model>_<field>_key`), so
-- `uniqueViolationTargets` reads a clash as ["staffId"].
-- ---------------------------------------------------------------------------
CREATE UNIQUE INDEX "AttendanceRecord_staffId_key"
  ON "AttendanceRecord" ("staffId")
  WHERE "timeOut" IS NULL;

-- A shift ends at or after it began ("Check-out must follow check-in.").
ALTER TABLE "AttendanceRecord"
  ADD CONSTRAINT "AttendanceRecord_times_check"
  CHECK ("timeOut" IS NULL OR "timeOut" >= "timeIn");

-- A correction keeps the times it replaced, which were themselves a shift,
-- and always says why ("An admin correction requires a reason.").
ALTER TABLE "AttendanceCorrection"
  ADD CONSTRAINT "AttendanceCorrection_values_check" CHECK (
    ("beforeOut" IS NULL OR "beforeOut" >= "beforeIn")
    AND btrim("reason") <> ''
  );

-- ---------------------------------------------------------------------------
-- Stock requests (plan §4.6, §7.6).
-- ---------------------------------------------------------------------------

-- The Store issues; it never requests ("Choose Kitchen or Bar.").
ALTER TABLE "StockRequest"
  ADD CONSTRAINT "StockRequest_location_check"
  CHECK ("location" IN ('KITCHEN', 'BAR'));

-- Whole packs above zero asked for ("Enter a whole quantity above zero."),
-- and never more sent than asked for ("…within the remaining request.").
ALTER TABLE "StockRequest"
  ADD CONSTRAINT "StockRequest_packs_check" CHECK (
    "qtyPacks" > 0
    AND "issuedPacks" BETWEEN 0 AND "qtyPacks"
  );

-- The status follows the packs sent: nothing for Pending, some for
-- Partially Issued, all for Issued. A rejection closes what is left, so a
-- Rejected request was never fully sent.
ALTER TABLE "StockRequest"
  ADD CONSTRAINT "StockRequest_status_check" CHECK (
    ("status" = 'PENDING' AND "issuedPacks" = 0)
    OR ("status" = 'PARTIALLY_ISSUED' AND "issuedPacks" > 0 AND "issuedPacks" < "qtyPacks")
    OR ("status" = 'ISSUED' AND "issuedPacks" = "qtyPacks")
    OR ("status" = 'REJECTED' AND "issuedPacks" < "qtyPacks")
  );

-- A rejection carries its reason ("Enter a rejection reason."), and only a
-- rejection does.
ALTER TABLE "StockRequest"
  ADD CONSTRAINT "StockRequest_reject_check" CHECK (
    ("status" = 'REJECTED') = ("rejectReason" IS NOT NULL)
    AND ("rejectReason" IS NULL OR btrim("rejectReason") <> '')
  );

-- ---------------------------------------------------------------------------
-- Vendors, purchases and waste (plan §4.6, §7.7, §7.8).
-- ---------------------------------------------------------------------------

-- "Enter the vendor name and phone."
ALTER TABLE "Vendor"
  ADD CONSTRAINT "Vendor_required_check"
  CHECK (btrim("name") <> '' AND btrim("phone") <> '');

-- Whole packs and a cost per pack above zero ("Choose a stock item and
-- positive unit cost."). Receiving is all at once (D39), so what was
-- received is nothing or the whole line, never more.
ALTER TABLE "PurchaseLine"
  ADD CONSTRAINT "PurchaseLine_values_check" CHECK (
    "position" >= 0
    AND "qtyPacks" > 0
    AND "costKobo" > 0
    AND "receivedPacks" BETWEEN 0 AND "qtyPacks"
  );

-- "Enter a whole quantity and a waste reason." The value is the coded
-- formula's (Q25), never negative.
ALTER TABLE "WasteEntry"
  ADD CONSTRAINT "WasteEntry_values_check"
  CHECK ("qty" > 0 AND "valueKobo" >= 0);

-- ---------------------------------------------------------------------------
-- Tasks, assets and repairs (plan §4.7, §7.9).
-- ---------------------------------------------------------------------------

-- "Enter a task description." A task links to a purchase only when it is a
-- Purchase task and to a repair only when it is a Maintenance task, as
-- `task.save` sets the links from the type; so a task links to one record
-- at most.
ALTER TABLE "Task"
  ADD CONSTRAINT "Task_values_check" CHECK (
    btrim("title") <> ''
    AND ("purchaseId" IS NULL OR "type" = 'PURCHASE')
    AND ("maintenanceId" IS NULL OR "type" = 'MAINTENANCE')
  );

-- "Enter a tag, name and quantity."
ALTER TABLE "Asset"
  ADD CONSTRAINT "Asset_values_check" CHECK (
    btrim("tag") <> ''
    AND btrim("name") <> ''
    AND "quantity" > 0
  );

-- "Enter a description and valid cost." A repair that is Fixed or Not
-- Fixed has its resolved date, set once on the first such move and never
-- reset (plan §17, R3), and no repair is resolved before it was reported.
ALTER TABLE "MaintenanceRecord"
  ADD CONSTRAINT "MaintenanceRecord_values_check" CHECK (
    btrim("description") <> ''
    AND "costKobo" >= 0
    AND ("status" NOT IN ('FIXED', 'NOT_FIXED') OR "resolvedOn" IS NOT NULL)
    AND ("resolvedOn" IS NULL OR "resolvedOn" >= "reportedOn")
  );
